/**
 * Google Drive Node - Version 1
 * Discriminator: resource=folder, operation=create
 */


interface Credentials {
  googleApi: CredentialReference;
  googleDriveOAuth2Api: CredentialReference;
}

/** Create a folder */
export type GoogleDriveV1FolderCreateParams = {
  resource: 'folder';
  operation: 'create';
/**
 * Authentication
 * @default serviceAccount
 */
    authentication?: 'serviceAccount' | 'oAuth2' | Expression<string>;
/**
 * The name of folder to create
 */
    name: string | Expression<string>;
/**
 * Options
 * @default {}
 */
    options?: {
    /** The IDs of the parent folders the file/folder should be saved in
     * @default []
     */
    parents?: Array<string | Expression<string>>;
  };
};

export type GoogleDriveV1FolderCreateNode = {
  type: 'n8n-nodes-base.googleDrive';
  version: 1;
  config: NodeConfig<GoogleDriveV1FolderCreateParams> & { credentials?: Credentials };
};